155	        Connection.Method method = attr("method").equalsIgnoreCase("POST") ?
156	            Connection.Method.POST : Connection.Method.GET;
157	
158	        Document owner = ownerDocument();
159	        Connection connection = owner != null? owner.connection().newRequest() : Jsoup.newSession();
160	        return connection.url(action)
161	            .data(formData())
162	            .method(method);
163	    }
