208	            if (name.length() == 0) continue;
209	            String type = el.attr("type");
210	
211	            if (type.equalsIgnoreCase("button") || type.equalsIgnoreCase("image")) continue; // browsers don't submit these
212	
213	            if (el.nameIs("select")) {
214	                boolean multiple = el.hasAttr("multiple");
215	                Elements selected = el.select("option[selected]");
216	                if (!selected.isEmpty()) {
217	                    if (multiple) {
218	                        for (Element option : selected) {
219	                            if (isEnabledOption(option))
220	                                data.add(HttpConnection.KeyVal.create(name, option.val()));
221	                        }
222	                    } else {
223	                        // single select: only the first enabled selected option counts; if none are enabled, submit nothing
224	                        for (Element option : selected) {
225	                            if (isEnabledOption(option)) {
226	                                data.add(HttpConnection.KeyVal.create(name, option.val()));
227	                                break;
228	                            }
229	                        }
230	                    }
231	                } else if (!multiple) {
232	                    // nothing marked selected: a single select defaults to its first enabled option
233	                    for (Element option : el.select("option")) {
234	                        if (isEnabledOption(option)) {
235	                            data.add(HttpConnection.KeyVal.create(name, option.val()));
236	                            break;
237	                        }
238	                    }
239	                }
240	                // a multiple select with no enabled selected option submits nothing
241	            } else if ("checkbox".equalsIgnoreCase(type) || "radio".equalsIgnoreCase(type)) {
242	                // only add checkbox or radio if they have the checked attribute
243	                if (el.hasAttr("checked")) {
244	                    final String val = el.val().length() >  0 ? el.val() : "on";
245	                    data.add(HttpConnection.KeyVal.create(name, val));
246	                }
247	            } else {
248	                data.add(HttpConnection.KeyVal.create(name, el.val()));
249	            }
250	        }
251	        return data;
252	    }
253	
254	    /**
255	     Check if a control is excluded by a disabled ancestor fieldset. A disabled fieldset disables its descendants,
256	     except for those inside its first {@code legend} child's subtree. A nested disabled fieldset stays disabled even
257	     when it sits within an outer fieldset's exempt legend.
258	     @param el the control to check
259	     @return true if the control is within a disabled fieldset without an exempting legend
260	     */
261	    private static boolean inDisabledFieldset(Element el) {
262	        Element child = el;
263	        for (Element parent = el.parent(); parent != null && !parent.nameIs("#root"); child = parent, parent = parent.parent()) {
264	            if (parent.nameIs("fieldset") && parent.hasAttr("disabled") && !isFirstLegendChild(child, parent))
265	                return true;
266	            // if exempted by this fieldset's first legend, keep climbing — an outer disabled fieldset may still apply
267	        }
268	        return false;
269	    }
270	
271	    /**
272	     Check if {@code child} is the first {@code legend} child of {@code fieldset}; the subtree of that legend is
273	     exempted from the fieldset's disabled state.
274	     */
275	    private static boolean isFirstLegendChild(Element child, Element fieldset) {
276	        if (!child.nameIs("legend")) return false;
277	        for (Element fieldsetChild : fieldset.children()) {
278	            if (fieldsetChild.nameIs("legend")) return fieldsetChild == child; // first legend encountered in tree order
279	        }
280	        return false;
281	    }
282	
283	    /**
284	     Check if an option is eligible for submission: not itself disabled, and not inside a disabled optgroup.
285	     @param option the option to check
286	     @return true if the option may be submitted
287	     */
288	    private static boolean isEnabledOption(Element option) {
289	        if (!option.nameIs("option") || option.hasAttr("disabled")) return false;
290	        Element parent = option.parent();
291	        if (parent != null && parent.nameIs("optgroup") && parent.hasAttr("disabled")) return false;
292	        return true;
293	    }
294	
295	    @Override
296	    public FormElement clone() {
297	        return (FormElement) super.clone();
298	    }
299	}
